-- packed by Syllinse pack.lua — run through Luraph before shipping. Do not edit.
return {
    Init = function(UI, Core, notify)
        local C = Core
        if type(C) ~= "table" or type(C.__unlock) ~= "function" or type(C.__n) ~= "string" then
            return
        end

        -- Luraph macro raw-mode shim. You may NOT declare a local/variable named
        -- LPH_* — Luraph reserves that prefix. So we install an identity fallback
        -- under that name via a STRING key built by concat so the literal token
        -- never appears. Raw: call sites resolve to this identity fn; after Luraph
        -- the call sites are replaced at compile time and this line is dead.
        do
            local k = "LPH" .. "_NO_VIRTUALIZE"
            local G = (type(getgenv) == "function") and getgenv() or _G
            if not G[k] then G[k] = function(f) return f end end
        end

        local NAME   = "Movement"
        -- CIPHER is base64 ([A-Za-z0-9+/=] only), emitted as ONE double-quoted line.
        local CIPHER = ""

        -- ── DECRYPT lives in a NO_VIRTUALIZE block ───────────────────────────
        -- Luraph virtualizes everything by default, turning these tight per-byte
        -- loops into interpreted VM bytecode (a big module → SECONDS to decrypt,
        -- hard freeze on weak executors). Keeping this block un-virtualized runs
        -- it at native speed. It is not the secret — the secret is MASTER, which
        -- lives only in the loader — so nothing is lost. Vars/strings still get
        -- obfuscated by Luraph regardless. The macro must wrap a function LITERAL.
        local decrypt = LPH_NO_VIRTUALIZE(function()
            local U32 = 4294967296
            local NX = {}
            for a = 0, 15 do for b = 0, 15 do
                local r,x,y,p,t = 0,a,b,1,0
                while t < 4 do local xb,yb = x%2,y%2 if xb~=yb then r=r+p end x=(x-xb)/2 y=(y-yb)/2 p=p*2 t=t+1 end
                NX[a*16+b] = r
            end end
            local function bxb(a,b) return NX[((a-a%16)/16)*16+(b-b%16)/16]*16 + NX[(a%16)*16+(b%16)] end
            local function bxor(a,b) a=a%U32 b=b%U32 local r,m,t=0,1,0 while t<4 do local ab,bb=a%256,b%256 r=r+bxb(ab,bb)*m a=(a-ab)/256 b=(b-bb)/256 m=m*256 t=t+1 end return r end
            local function mul32(a,b) a=a%U32 b=b%U32 local ah=(a-a%65536)/65536 local al=a%65536 return (((ah*b)%65536)*65536+al*b)%U32 end
            local function shr(x,n) local d,k=1,0 while k<n do d=d*2 k=k+1 end return (x-(x%d))/d end
            local function rotl(x,n) x=x%U32 local pw,k=1,0 while k<n do pw=pw*2 k=k+1 end local lf=mul32(x,pw) local dp k=0 dp=1 while k<(32-n) do dp=dp*2 k=k+1 end return (lf+(x-(x%dp))/dp)%U32 end
            local function chash(s,sd) local h=(2166136261+(sd or 0))%U32 local ac=5381 local i,n=1,#s while i<=n do local c=string.byte(s,i) h=bxor(h,c) h=mul32(h,16777619) ac=(mul32(ac,33)+c+i)%U32 h=bxor(h,rotl(ac,(c%23)+1)) h=rotl(h,(i%13)+3) i=i+1 end h=bxor(h,shr(h,16)) h=mul32(h,2246822519) h=bxor(h,shr(h,13)) h=mul32(h,3266489917) h=bxor(h,shr(h,16)) return h end
            local HEX="0123456789abcdef"
            local function tohex(v) local s,i="",0 while i<8 do local nb=v%16 v=(v-nb)/16 s=string.sub(HEX,nb+1,nb+1)..s i=i+1 end return s end
            local function deriveKey(m,nm) local base=m.."\0"..nm.."\0syllinse" local k,r="",0 while r<8 do k=k..tohex(chash(base.."|"..r,mul32(r,2654435761))) r=r+1 end return k end
            -- 1) masked key from the loader (only a real loader, holding MASTER, makes it)
            local masked = C.__unlock(NAME)
            if type(masked) ~= "string" or #masked < 16 then return nil end

            -- 2) unwrap with the per-session pad recomputed from Core.__n
            local pad = deriveKey(C.__n, NAME)
            local kb = {}
            for i = 1, #masked do
                local a = string.byte(masked, i)
                local b = string.byte(pad, ((i - 1) % #pad) + 1)
                kb[i] = string.char(bxb(a, b))
            end
            local key = table.concat(kb)

            -- 3) base64 decode → array of cipher BYTES
            local B = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
            local R = {}
            for i = 1, #B do R[string.byte(B, i)] = i - 1 end
            local vals, vc = {}, 0
            for p = 1, #CIPHER do
                local v = R[string.byte(CIPHER, p)]
                if v then vc = vc + 1; vals[vc] = v end
            end
            local cb, bc, j = {}, 0, 1
            while j <= vc do
                local c1 = vals[j] or 0
                local c2 = vals[j+1] or 0
                local c3 = vals[j+2]
                local c4 = vals[j+3]
                local nn = c1 * 262144 + c2 * 4096 + (c3 or 0) * 64 + (c4 or 0)
                bc = bc + 1; cb[bc] = (nn - nn % 65536) / 65536 % 256
                if c3 then bc = bc + 1; cb[bc] = (nn - nn % 256) / 256 % 256 end
                if c4 then bc = bc + 1; cb[bc] = nn % 256 end
                j = j + 4
            end

            -- 4) XOR-decrypt → source, keystream generated lazily and spread over
            --    frames via C.__yield. 200-byte window (executors cap unpack args).
            local yield = (type(C.__yield) == "function") and C.__yield or nil
            local ks_s = chash(key, 0); if ks_s == 0 then ks_s = 2654435761 end
            local ksb1, ksb2, ksb3, ksb4, ksi = 0, 0, 0, 0, 5
            local function nextKS()
                if ksi > 4 then
                    ks_s = bxor(ks_s, mul32(ks_s, 8192)); ks_s = bxor(ks_s, (ks_s - ks_s % 131072) / 131072); ks_s = bxor(ks_s, mul32(ks_s, 32)); ks_s = ks_s % U32
                    local t = ks_s
                    ksb1 = t % 256; t = (t - ksb1) / 256
                    ksb2 = t % 256; t = (t - ksb2) / 256
                    ksb3 = t % 256; t = (t - ksb3) / 256
                    ksb4 = t
                    ksi = 1
                end
                local b
                if     ksi == 1 then b = ksb1
                elseif ksi == 2 then b = ksb2
                elseif ksi == 3 then b = ksb3
                else                 b = ksb4 end
                ksi = ksi + 1
                return b
            end
            local pieces, pc, i, since = {}, 0, 1, 0
            while i <= bc do
                local e = i + 199 if e > bc then e = bc end
                local buf, bi = {}, 0
                for k = i, e do bi = bi + 1; buf[bi] = bxb(cb[k], nextKS()) end
                pc = pc + 1; pieces[pc] = string.char(table.unpack(buf, 1, bi))
                i = e + 1
                since = since + 1
                if yield and since >= 500 then since = 0; yield() end
            end
            return table.concat(pieces)
        end)

        local src = decrypt()
        if type(src) ~= "string" or #src == 0 then return end

        local fn = loadstring(src, "=" .. NAME)
        if not fn then return end

        local real = fn()                        -- inner module returns a TABLE
        if type(real) == "table" and type(real.Init) == "function" then
            return real.Init(UI, Core, notify)   -- forward the loader's exact args
        end
        return real
    end,
}
